import { readFileSync, mkdirSync, writeFileSync } from "node:fs";
const source = readFileSync("v2/src/engine/temple.ts", "utf8")
  .replace(
    'import roomData from "../data/rooms.json";',
    `const roomData = ${readFileSync("v2/src/data/rooms.json", "utf8").trim()} as const;`,
  )
  .replace(
    "roomData as Record<RoomKey, Room>",
    "roomData as unknown as Record<RoomKey, Room>",
  );
mkdirSync("supabase/functions/_shared", { recursive: true });
writeFileSync(
  "supabase/functions/_shared/temple.ts",
  "// Generated by scripts/sync-edge-engine.mjs. Do not edit directly.\n" +
    source,
);
